style.css:
@-moz-document domain("google.com"), regexp("https://www\.google\.com/\??.*") {
/* --- GLOBAL AERO AMBIENT LANDSCAPE --- */
    body {
        background: linear-gradient(180deg, #1aa3ff 0%, #66ccff 40%, #b3f0ff 65%, #33cc33 85%, #009933 100%) !important;
        background-attachment: fixed !important;
        min-height: 100vh !important;
        position: relative !important;
    }

    /* Aurora Light Overlay Generated Dynamically via Pseudo-element */
    body::before {
        content: '' !important;
        position: fixed !important;
        width: 200% !important;
        height: 200% !important;
        top: -50% !important;
        left: -50% !important;
        background: radial-gradient(circle at 30% 20%, rgba(255, 255, 255, 0.35) 0%, rgba(255, 255, 255, 0) 50%),
                    radial-gradient(circle at 70% 60%, rgba(0, 255, 150, 0.25) 0%, rgba(0, 255, 150, 0) 60%),
                    radial-gradient(circle at 40% 80%, rgba(0, 150, 255, 0.35) 0%, rgba(0, 150, 255, 0) 50%) !important;
        z-index: -2 !important;
        pointer-events: none !important;
    }

    /* --- THE GLOSSY SKEUOMORPHIC ORB --- */
    body::after {
        content: '' !important;
        position: fixed !important;
        top: 15% !important;
        left: 50% !important;
        transform: translateX(-50%) !important;
        width: 120px !important;
        height: 120px !important;
        border-radius: 50% !important;
        background: radial-gradient(circle at 35% 35%, rgba(255, 255, 255, 1) 0%, rgba(0, 210, 255, 0.7) 40%, rgba(0, 102, 204, 0.9) 80%) !important;
        box-shadow: inset -10px -15px 25px rgba(0, 51, 102, 0.8), 
                    0 15px 30px rgba(0, 50, 100, 0.35),
                    0 0 40px rgba(0, 255, 255, 0.2) !important;
        z-index: -1 !important;
    }

    /* --- SEARCH BAR GLASSMORPHISM --- */
    input[type="text"], textarea, .gLFyf, #searchbox, .search-box-input {
        background: rgba(255, 255, 255, 0.25) !important;
        backdrop-filter: blur(20px) saturate(150%) !important;
        -webkit-backdrop-filter: blur(20px) saturate(150%) !important;
        border: 1px solid rgba(255, 255, 255, 0.55) !important;
        border-radius: 30px !important;
        padding: 12px 24px !important;
        color: #003366 !important;
        font-weight: 600 !important;
        box-shadow: 0 10px 35px rgba(0, 50, 120, 0.2), 
                    inset 0 2px 4px rgba(255, 255, 255, 0.6) !important;
        transition: all 0.3s ease !important;
    }

    /* Glow state focus targeting */
    input[type="text"]:focus, textarea:focus, .gLFyf:focus, #searchbox:focus {
        box-shadow: 0 10px 40px rgba(0, 150, 255, 0.4), 
                    0 0 0 3px rgba(255, 255, 255, 0.5),
                    inset 0 2px 4px rgba(255, 255, 255, 0.6) !important;
        outline: none !important;
    }

    /* --- LIQUID GEL BUTTONS --- */
    button, input[type="submit"], input[type="button"], .gNO89b, .Tg76b {
        background: linear-gradient(to bottom, #33ccff 0%, #0088cc 50%, #0066cc 51%, #0099ff 100%) !important;
        color: white !important;
        border: 1px solid #004488 !important;
        border-radius: 20px !important;
        padding: 10px 24px !important;
        font-size: 1rem !important;
        font-weight: bold !important;
        cursor: pointer !important;
        text-shadow: 0 -1px 1px rgba(0, 30, 90, 0.7) !important;
        box-shadow: inset 0 2px 3px rgba(255, 255, 255, 0.7),
                    0 3px 6px rgba(0, 0, 0, 0.15) !important;
        transition: all 0.2s cubic-bezier(0.175, 0.885, 0.32, 1.275) !important;
    }

    button:hover, input[type="submit"]:hover {
        filter: brightness(1.1) !important;
        transform: scale(1.04) !important;
        box-shadow: inset 0 2px 3px rgba(255, 255, 255, 0.8),
                    0 5px 12px rgba(0, 50, 100, 0.3) !important;
    }

    /* Hide conflicting search layout graphics */
    .lnXdpd, .logo svg {
        opacity: 0 !important;
        pointer-events: none !important;
    }
}
